const userPrompt = $json.chatInput || $json.text || '';

if (!userPrompt || userPrompt.trim().length === 0) {
  throw new Error('No prompt provided. Please type a topic, e.g. "Sparks Fostering info session about faith-friendly placements".');
}

// Try to extract brand name from patterns like "for X about/regarding..."
let brand = 'Sparks Fostering'; // default fallback
const forMatch = userPrompt.match(/for\s+([A-Z][A-Za-z0-9&' ]{2,40}?)(?:\s+about|\s+regarding|,|:|$)/i);
if (forMatch) {
  brand = forMatch[1].trim();
}

return [{
  json: {
    userPrompt: userPrompt.trim(),
    brand,
    timestamp: new Date().toISOString()
  }
}];

