const message = $input.first().json.choices?.[0]?.message?.content || '';
const prep = $('Prep Prompt').first().json;

let result;
try {
  const cleaned = message.replace(/```json|```/g, '').trim();
  result = JSON.parse(cleaned);
} catch (e) {
  result = {
    headline: 'DRAFT — needs manual review',
    instagram_caption: message || 'AI did not return valid content. See raw output in Trello card.',
    facebook_caption: '',
    suggested_hashtags: '',
    sensitivity_flag: 'true'
  };
}

return [{
  json: {
    ...result,
    brand: prep.brand,
    userPrompt: prep.userPrompt,
    timestamp: prep.timestamp
  }
}];

const promptUsed = $('AI Agent - Write Illustration Brief').first().json.output;
const taskId = $input.first().json.data?.taskId || $input.first().json.taskId;

if (!taskId) {
  throw new Error('Kie.ai did not return a taskId — check API key and request body.');
}

return [{
  json: {
    illustrationPromptUsed: promptUsed,
    taskId,
    style: 'flat cartoon illustration, claymation-inspired, no photorealistic humans'
  }
}];

const promptUsed = $('Capture Task ID').first().json.illustrationPromptUsed;
const style = $('Capture Task ID').first().json.style;
const captions = $('Parse Caption Response').first().json;
const resultData = $input.first().json;

let imageUrl = '';
try {
  const parsed = typeof resultData.data.resultJson === 'string'
    ? JSON.parse(resultData.data.resultJson)
    : resultData.data.resultJson;
  imageUrl = parsed.resultUrls?.[0] || '';
} catch (e) {
  imageUrl = '';
}

return [{
  json: {
    ...captions,
    illustrationPromptUsed: promptUsed,
    imageUrl,
    style
  }
}];

